WITH parsed AS (SELECT id, host, log_ts, status_code, payload_json, SIZE(context) AS num_context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version FROM app_logs WHERE log_ts >= '2025-08-01') SELECT CASE WHEN status_code >= 455 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, host, COUNT_IF(host = 'h2') AS h2_events, COUNT(*) AS num_rows, COUNT(DISTINCT host) AS distinct_hosts, SUM(status_code) FILTER (WHERE host = 'h4') AS h4_total_status_code FROM parsed GROUP BY 1, 2, 3 ORDER BY status_code_tier NULLS LAST;
